css:
/* East Texas Mack type and button conventions, applied site-wide.
   Headings are Oswald, uppercase and set tight; buttons and eyebrows are Inter. */
.bz-block :is(h1, h2, h3) { font-weight: var(--weight-heading); text-transform: uppercase; letter-spacing: 0; }
.bz-block h1 { line-height: 1.08; }
.bz-block :is(h2, h3) { line-height: normal; }
.bz-block .bz-eyebrow { font: 700 var(--text-eyebrow) / 1.4 var(--font-body); letter-spacing: 1.5px; margin: 0 0 10px; }
.bz-btn { font-family: var(--font-body); font-weight: 600; border-radius: var(--radius-input); }
.bz-btn--primary { color: var(--card); }
.bz-btn--primary:hover { background: var(--accent-dark); }
.bz-btn--secondary:hover { opacity: .9; }
.bz-btn--link { text-decoration: none; padding: 0; font-size: 15px; color: var(--accent-dark); }
.bz-btn--link:hover { opacity: .8; }
